            logit_backward_kernel,
            (
                grad_contig,
                self_contig,
                out,
            ),
            n_total,
            block,
            num_warps,
            eps=eps if eps is not None else 0.0,
            HAS_EPS=eps is not None,
            FAST_RCP=out.dtype in (torch.float16, torch.bfloat16),
            OUT_DTYPE=_to_triton_dtype(out.dtype),
